//! Generates out/ios/generated/BackendServices.swift for the iOS app (ios/).
//!
//! The message types themselves are generated by protoc-gen-swift (see
//! ios/gen-swift-protos.sh); this file adds:
//! - `BackendMethods.byName`, mapping the camelCase method names the web
//!   pages post to (/_anki/<name>, as in ts/lib/generated/backend.ts) to the
//!   (service, method) indices expected by Backend::run_service_method.
//! - `BackendErrorKinds.names`, mapping BackendError.Kind values to their
//!   proto names (eg SYNC_AUTH_ERROR).
//! - typed async wrappers in an `extension AnkiBackend`.

use std::fmt::Write as WriteFmt;
use std::path::Path;

use anki_io::create_dir_all;
use anki_io::write_file_if_changed;
use anki_proto_gen::BackendService;
use anki_proto_gen::Method;
use anyhow::Result;
use inflections::Inflect;
use prost_reflect::DescriptorPool;
use prost_reflect::MessageDescriptor;

/// Names already used by AnkiBackend itself (ios/AnkiApp/Backend and
/// ios/AnkiApp/Rpc). A generated wrapper with one of these names gets an
/// `Rpc` suffix instead, eg abortSync -> abortSyncRpc.
const RESERVED_METHOD_NAMES: &[&str] = &["call", "run", "rpc", "rpcMessage", "abortSync"];

pub(crate) fn write_swift_interface(
    pool: &DescriptorPool,
    services: &[BackendService],
) -> Result<()> {
    let root = Path::new("../../out/ios/generated");
    create_dir_all(root)?;

    let mut by_name = String::new();
    let mut frontend = String::new();
    let mut wrappers = String::new();

    for service in services {
        // Like the TypeScript code: AnkiDroid's methods are not exposed.
        if service.name == "BackendAnkidroidService" {
            continue;
        }
        // FrontendService methods are listed so pages' requests can be
        // routed, but they are not handled by run_service_method: the host
        // app must implement them (as qt/aqt/mediasrv.py does on desktop).
        let frontend_only = service.name == "BackendFrontendService";
        for method in service.all_methods() {
            let name = method.name.to_camel_case();
            writeln!(
                by_name,
                "        \"{name}\": (service: {}, method: {}),",
                service.index, method.index
            )
            .unwrap();
            if frontend_only {
                writeln!(frontend, "        \"{name}\",").unwrap();
            } else {
                write_wrapper(service, method, &mut wrappers);
            }
        }
    }

    let error_kinds = error_kind_names(pool);

    let out = format!(
        r#"// Copyright: Ankitects Pty Ltd and contributors
// License: GNU AGPL, version 3 or later; http://www.gnu.org/licenses/agpl.html

// Generated by rslib/proto/swift.rs - do not edit.

import Foundation
import SwiftProtobuf

/// The backend's RPC methods, by the camelCase name the web pages use when
/// posting to /_anki/<name>.
enum BackendMethods {{
    /// (service, method) indices, as expected by anki_bridge_rpc().
    static let byName: [String: (service: UInt32, method: UInt32)] = [
{by_name}    ]

    /// Methods of FrontendService. They are not implemented by the Rust
    /// backend, and must be handled by the app (see qt/aqt/mediasrv.py).
    static let frontendMethods: Set<String> = [
{frontend}    ]
}}

/// The proto names of anki.backend.BackendError.Kind values.
enum BackendErrorKinds {{
    static let names: [Int: String] = [
{error_kinds}    ]
}}

extension AnkiBackend {{
{wrappers}}}
"#
    );
    write_file_if_changed(root.join("BackendServices.swift"), out)?;
    Ok(())
}

fn error_kind_names(pool: &DescriptorPool) -> String {
    let kind = pool
        .get_enum_by_name("anki.backend.BackendError.Kind")
        .expect("BackendError.Kind");
    let mut out = String::new();
    for value in kind.values() {
        writeln!(out, "        {}: \"{}\",", value.number(), value.name()).unwrap();
    }
    out
}

fn write_wrapper(service: &BackendService, method: &Method, out: &mut String) {
    let mut name = method.name.to_camel_case();
    if RESERVED_METHOD_NAMES.contains(&name.as_str()) {
        name.push_str("Rpc");
    }
    let name = escape_identifier(&name);
    let service_idx = service.index;
    let method_idx = method.index;
    let output = swift_type(&method.proto.output());
    let comments = method
        .comments
        .as_ref()
        .map(|c| {
            c.lines()
                .map(|line| match line.trim() {
                    "" => "    ///\n".to_string(),
                    line => format!("    /// {line}\n"),
                })
                .collect::<String>()
        })
        .unwrap_or_default();
    let (params, input_expr) = match method.input() {
        Some(input) => (
            format!("_ input: {}", swift_type(&input)),
            "input".to_string(),
        ),
        None => (String::new(), "Anki_Generic_Empty()".to_string()),
    };
    let call = format!(
        "rpcMessage(service: {service_idx}, method: {method_idx}, {input_expr}, as: {output}.self)"
    );
    if method.output().is_some() {
        writeln!(
            out,
            "{comments}    func {name}({params}) async throws -> {output} {{
        try await {call}
    }}
"
        )
        .unwrap();
    } else {
        writeln!(
            out,
            "{comments}    func {name}({params}) async throws {{
        _ = try await {call}
    }}
"
        )
        .unwrap();
    }
}

/// The name protoc-gen-swift gives a message: the package's components in
/// UpperCamelCase joined by underscores, then the message name, with nested
/// messages as nested Swift types. Eg anki.import_export.ImportResponse ->
/// Anki_ImportExport_ImportResponse; anki.decks.Deck.Normal ->
/// Anki_Decks_Deck.Normal.
fn swift_type(message: &MessageDescriptor) -> String {
    let package = message.package_name();
    let prefix: String = package
        .split('.')
        .map(|component| format!("{}_", upper_camel_case(component)))
        .collect();
    let relative = message
        .full_name()
        .strip_prefix(package)
        .and_then(|n| n.strip_prefix('.'))
        .expect("message in package");
    let mut parts = relative.split('.');
    let mut name = format!("{prefix}{}", parts.next().unwrap());
    for nested in parts {
        // protoc-gen-swift renames nested types that clash with Swift
        // keywords/builtins; none are used by the RPC methods today.
        assert!(
            !SWIFT_RESERVED_TYPE_NAMES.contains(&nested),
            "nested message {} would be renamed by protoc-gen-swift",
            message.full_name()
        );
        name.push('.');
        name.push_str(nested);
    }
    name
}

const SWIFT_RESERVED_TYPE_NAMES: &[&str] = &[
    "Any",
    "Protocol",
    "Self",
    "Type",
    "Int",
    "Int32",
    "Int64",
    "UInt32",
    "UInt64",
    "String",
    "Bool",
    "Float",
    "Double",
    "Data",
    "Error",
    "Equatable",
    "Hashable",
    "Message",
    "Enum",
    "Extensions",
    "Sendable",
];

/// Matches protoc-gen-swift's NamingUtils.toUpperCamelCase for package
/// components: underscores are removed and the following letter capitalized.
fn upper_camel_case(s: &str) -> String {
    s.split('_')
        .filter(|w| !w.is_empty())
        .map(|w| {
            let mut chars = w.chars();
            let first = chars.next().unwrap();
            first.to_uppercase().chain(chars).collect::<String>()
        })
        .collect()
}

fn escape_identifier(name: &str) -> String {
    const KEYWORDS: &[&str] = &[
        "as",
        "associatedtype",
        "break",
        "case",
        "catch",
        "class",
        "continue",
        "default",
        "defer",
        "deinit",
        "do",
        "else",
        "enum",
        "extension",
        "fallthrough",
        "false",
        "for",
        "func",
        "guard",
        "if",
        "import",
        "in",
        "init",
        "inout",
        "internal",
        "is",
        "let",
        "nil",
        "operator",
        "private",
        "protocol",
        "public",
        "repeat",
        "rethrows",
        "return",
        "self",
        "static",
        "struct",
        "subscript",
        "super",
        "switch",
        "throw",
        "throws",
        "true",
        "try",
        "typealias",
        "var",
        "where",
        "while",
    ];
    if KEYWORDS.contains(&name) {
        format!("`{name}`")
    } else {
        name.to_string()
    }
}
